import {createTeamChallenge} from './team-challenge.js';
import {lessons,xpFor,escapeHTML as esc} from './learning.js';
import {badgeDefinitions,levelFor,currentStreak,dueTopics,dayKey} from './journey-data.js';
import {quests} from './quest-science.js';
export function createJourney(root,api){
 function render(){const s=api.getState(),xp=xpFor(s),level=levelFor(xp),due=dueTopics(s.quizAttempts).map(id=>lessons.find(l=>l.id===id)).filter(Boolean),today=dayKey(),now=Date.parse(today+'T00:00:00Z');
 root.innerHTML=`<header class="campus-heading"><div><span class="eyebrow">MY LEARNING JOURNEY / HÀNH TRÌNH CỦA TÔI</span><h1 data-page-heading tabindex="-1">Kiến thức lớn lên.<br><em>Dấu chân ở lại.</em></h1><p>Nhìn lại điều đã hiểu, chọn một bước tiếp theo và giữ nhịp khám phá của riêng bạn.</p></div><a href="#/notebook" class="campus-button pale">Mở quyển sổ của tôi ↗</a></header><div class="journey-dashboard"><section class="journey-identity campus-card"><div class="journey-avatar" aria-hidden="true">${esc(s.name[0]?.toUpperCase()||'V')}</div><div><span class="campus-kicker">CẤP ${level.level} / ${level.name.toUpperCase()}</span><h2>${esc(s.name)}</h2><p>${xp} XP đã tích lũy · ${s.completed.length}/${lessons.length} bài học</p></div><div class="journey-level"><div><span>Đến cột mốc tiếp theo</span><strong>${xp} / ${level.next} XP</strong></div><div class="journey-level-track"><span style="width:${level.progress*100}%"></span></div><p>XP từ hoạt động đã hoàn thành. Xem lại bài hoặc thử lại không cộng lặp.</p></div><form id="name-form" class="journey-name-form"><label for="explorer-name">Tên trên hành trình</label><input id="explorer-name" class="name-input" value="${esc(s.name)}" maxlength="40" required><button class="campus-button" type="submit">Lưu tên</button></form></section><section class="journey-streak campus-card"><span class="campus-kicker">NHỊP HỌC THỰC TẾ</span><strong>${currentStreak(s.activityDays,today)} <small>ngày liên tiếp</small></strong><div class="journey-calendar">${Array.from({length:14},(_,i)=>{const d=new Date(now-(13-i)*86400000).toISOString().slice(0,10),active=s.activityDays.includes(d);return `<span class="${active?'active':''}" title="${d}${active?' · Có hoạt động học':' · Chưa ghi nhận hoạt động'}" aria-label="${d}${active?' có hoạt động học':' chưa ghi nhận'}">${Number(d.slice(-2))}</span>`}).join('')}</div><p>Ghi nhận khi làm bài, lưu thí nghiệm hoặc hoàn thành hoạt động. Múi giờ Việt Nam; dữ liệu cũ chưa có ngày học sẽ không được tự tạo.</p></section></div><div class="journey-section-heading"><div><span class="campus-kicker">MỖI KHÁM PHÁ MỘT DẤU MỐC</span><h2>Bộ sưu tập thành tựu.</h2></div><span>${s.earnedBadgeIds.length}/${badgeDefinitions.length} huy hiệu</span></div><div class="journey-achievements">${badgeDefinitions.map(b=>`<article class="campus-card achievement-card ${s.earnedBadgeIds.includes(b.id)?'earned':''}"><span class="achievement-emblem" aria-hidden="true">${s.earnedBadgeIds.includes(b.id)?'✳':'◌'}</span><h3>${b.name}</h3><p>${b.description}</p><small>${s.earnedBadgeIds.includes(b.id)?'Đã mở khóa':'Đang chờ khám phá'}</small></article>`).join('')}</div><div class="journey-detail-grid"><section class="campus-card"><span class="campus-kicker">BẢN ĐỒ HỌC LIỆU</span><h2>Từng chủ đề, từng bước.</h2><div class="journey-grade-map">${[6,7,8,9,10,11,12].map(g=>{const list=lessons.filter(l=>l.grade===g),count=list.filter(l=>s.completed.includes(l.id)).length;return `<div><span>Lớp ${g}</span><div class="journey-grade-dots">${list.map(l=>`<button data-action="lesson" data-id="${l.id}" title="${esc(l.title)}" aria-label="${esc(l.title)}${s.completed.includes(l.id)?', đã hoàn thành':''}" class="${s.completed.includes(l.id)?'done':''}">${s.completed.includes(l.id)?'✓':'·'}</button>`).join('')}</div><small>${count}/${list.length}</small></div>`}).join('')}</div></section><section class="campus-card"><span class="campus-kicker">GỢI Ý TỪ LƯỢT LÀM BÀI</span><h2>Điều nên nhìn lại.</h2>${due.length?`<p>Những chủ đề có lượt trả lời gần nhất chưa đúng. Đây là gợi ý ôn tập, không phải chẩn đoán năng lực.</p><div class="journey-due">${due.map(l=>`<button data-action="lesson" data-id="${l.id}"><span>${l.title}</span><b>Ôn lại ↗</b></button>`).join('')}</div>`:'<p>Chưa có chủ đề cần ôn được ghi nhận. Hãy làm một câu kiểm tra trong học liệu để tạo dữ liệu phản hồi cho riêng bạn.</p><a class="campus-link" href="#/explore">Chọn một bài học →</a>'}<h3 class="journey-quest-heading">Dấu chân BioQuest</h3><div class="journey-quest-marks">${quests.map(q=>`<span class="${s.completedQuests.includes(q.id)?'done':''}">${s.completedQuests.includes(q.id)?'✓':'◌'} ${q.badge}</span>`).join('')}</div><a href="#/quests" class="campus-link">Tiếp tục nhiệm vụ →</a></section></div><section id="journey-team-challenge"></section><p class="campus-storage">Hồ sơ lưu trên trình duyệt và địa chỉ website hiện tại. Chưa có lớp học trực tuyến hoặc bảng xếp hạng giữa nhiều tài khoản. <a href="#/notebook">Xuất sổ tay để giữ bản sao ↗</a></p>`;
 createTeamChallenge(root.querySelector('#journey-team-challenge'),api);
 }return {render,setActive(value){if(value)render()}};
}
